func (q *Queries) NextGroupWithMembers(ctx context.Context, groupID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, nextGroupWithMembers, groupID)
	var group_id int64
	err := row.Scan(&group_id)
	return group_id, err
}

